import { z } from 'zod';
import type { Address } from './account';

// Checkout. The Cart is bought as a whole; prices and the Shipping fee always come from the database.
export const CheckoutInput = z.object({ addressId: z.string().min(1) });
export type CheckoutInput = z.input<typeof CheckoutInput>;
// The `Idempotency-Key` header: generated by the client once per checkout attempt and reused on retries.
export const IdempotencyKey = z.string().trim().min(1).max(100);

export const ORDER_STATUSES = ['pending_payment', 'paid', 'shipped', 'completed', 'cancelled', 'expired'] as const;
export type OrderStatus = (typeof ORDER_STATUSES)[number];

// A copy of the Variant as it was at checkout, so later catalog edits never change the Order.
export type OrderItem = {
  variantId: string;
  productName: string;
  sku: string;
  options: string[];
  unitPrice: number;
  quantity: number;
  lineTotal: number;
};
export type OrderSummary = {
  id: string;
  number: string;
  status: OrderStatus;
  total: number;
  createdAt: string;
};
export type Order = OrderSummary & {
  items: OrderItem[];
  subtotal: number;
  shippingFee: number;
  // The Address copied at checkout.
  address: Omit<Address, 'id'>;
};

// Why checkout refused a Cart line: not enough Stock, or no longer sold.
export type ShortItem = { variantId: string; sku: string; productName: string; requested: number; available: number; archived: boolean };

export const orderTotal = (items: { unitPrice: number; quantity: number }[], shippingFee: number) =>
  items.reduce((sum, i) => sum + i.unitPrice * i.quantity, 0) + shippingFee;

// The Store is in Indonesia, so the day in the Order number is the Jakarta (UTC+7, no DST) date.
const JAKARTA_OFFSET_MS = 7 * 60 * 60 * 1000;
// YYYYMMDD in Jakarta: the day whose sequence the Order number counts in.
export const orderNumberDay = (at: Date) => new Date(at.getTime() + JAKARTA_OFFSET_MS).toISOString().slice(0, 10).replaceAll('-', '');
export const formatOrderNumber = (at: Date, sequence: number) => `ORD-${orderNumberDay(at)}-${String(sequence).padStart(4, '0')}`;

// How long a pending_payment Order holds its Stock while the Customer pays.
export const PAYMENT_WINDOW_MS = 30 * 60 * 1000;
